APP_ICON_ICO_B64 = """"""

def get_app_icon():
    """Usa o grilinho.ico fornecido pelo usuário, embutido no código."""
    ico_data = base64.b64decode(APP_ICON_ICO_B64)
    # O Qt consegue carregar o ICO diretamente a partir dos bytes.
    pixmap = QPixmap()
    if pixmap.loadFromData(ico_data, "ICO"):
        return QIcon(pixmap)

    # Fallback defensivo: não impede a aplicação de iniciar caso o plugin
    # ICO não esteja disponível no backend gráfico do Qt.
    return QIcon()


def make_ui_icon(kind, color="#B9C0C8", size=20):
    """Cria ícones vetoriais Qt sem emojis e sem fundos. Todas as primitivas
    usam coordenadas compatíveis com os overloads do PyQt6 (QPointF/QRectF).
    """
    size = int(size)
    pm = QPixmap(size, size)
    pm.fill(Qt.transparent)

    painter = QPainter(pm)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)

    pen = QPen(QColor(color), 1.7)
    pen.setCapStyle(Qt.RoundCap)
    pen.setJoinStyle(Qt.RoundJoin)
    painter.setPen(pen)
    painter.setBrush(Qt.NoBrush)

    def line(x1, y1, x2, y2):
        painter.drawLine(QPointF(float(x1), float(y1)), QPointF(float(x2), float(y2)))

    def rect(x, y, w, h, radius=0):
        r = QRectF(float(x), float(y), float(w), float(h))
        if radius:
            painter.drawRoundedRect(r, float(radius), float(radius))
        else:
            painter.drawRect(r)

    def arc(x, y, w, h, start16, span16):
        painter.drawArc(QRectF(float(x), float(y), float(w), float(h)), int(start16), int(span16))

    c = size / 2.0

    if kind == "menu":
        line(4, 6, size - 4, 6)
        line(4, c, size - 4, c)
        line(4, size - 6, size - 4, size - 6)

    elif kind == "chevron_left":
        line(size * 0.62, size * 0.22, size * 0.34, c)
        line(size * 0.34, c, size * 0.62, size * 0.78)

    elif kind == "chevron_right":
        line(size * 0.38, size * 0.22, size * 0.66, c)
        line(size * 0.66, c, size * 0.38, size * 0.78)

    elif kind == "sync":
        arc(4, 5, size - 8, size - 8, 40 * 16, 220 * 16)
        arc(4, 5, size - 8, size - 8, 220 * 16, 120 * 16)
        line(size - 5, 6, size - 5, 10)
        line(size - 5, 6, size - 9, 6)
        line(5, size - 6, 5, size - 10)
        line(5, size - 6, 9, size - 6)

    elif kind == "reload":
        arc(4, 4, size - 8, size - 8, 40 * 16, 290 * 16)
        line(size - 5, 5, size - 5, 10)
        line(size - 5, 5, size - 10, 5)

    elif kind == "export":
        rect(4, 4, size - 8, size - 8)
        line(c, 7, c, size - 6)
        line(c - 3, size - 9, c, size - 6)
        line(c + 3, size - 9, c, size - 6)

    elif kind == "play":
        painter.setPen(Qt.NoPen)
        painter.setBrush(QColor(color))
        painter.drawPolygon(QPolygonF([
            QPointF(size * 0.38, size * 0.23),
            QPointF(size * 0.38, size * 0.77),
            QPointF(size * 0.76, c),
        ]))

    elif kind == "pause":
        painter.setPen(Qt.NoPen)
        painter.setBrush(QColor(color))
        painter.drawRoundedRect(QRectF(size * 0.28, size * 0.22, size * 0.15, size * 0.56), 1.5, 1.5)
        painter.drawRoundedRect(QRectF(size * 0.57, size * 0.22, size * 0.15, size * 0.56), 1.5, 1.5)

    elif kind == "volume":
        painter.setPen(pen)
        painter.drawPolygon(QPolygonF([
            QPointF(size * 0.20, c - 2.5),
            QPointF(size * 0.38, c - 2.5),
            QPointF(size * 0.57, size * 0.27),
            QPointF(size * 0.57, size * 0.73),
            QPointF(size * 0.38, c + 2.5),
            QPointF(size * 0.20, c + 2.5),
        ]))
        arc(size * 0.47, size * 0.31, size * 0.38, size * 0.38, -45 * 16, 90 * 16)

    elif kind == "maximize":
        # Quatro cantos com setas diagonais, sem formar um quadrado fechado.
        g = size * 0.24
        e = size * 0.46
        line(e, g, g, g); line(g, g, g, e)
        line(size-e, g, size-g, g); line(size-g, g, size-g, e)
        line(g, size-e, g, size-g); line(g, size-g, e, size-g)
        line(size-g, size-e, size-g, size-g); line(size-g, size-g, size-e, size-g)

    elif kind == "brain":
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        painter.drawEllipse(QRectF(size * 0.18, size * 0.33, size * 0.18, size * 0.18))
        painter.drawEllipse(QRectF(size * 0.64, size * 0.33, size * 0.18, size * 0.18))
        painter.drawEllipse(QRectF(size * 0.42, size * 0.14, size * 0.16, size * 0.16))
        painter.drawEllipse(QRectF(size * 0.42, size * 0.66, size * 0.16, size * 0.16))
        arc(size * 0.12, size * 0.30, size * 0.76, size * 0.40, 0, 180 * 16)
        arc(size * 0.08, size * 0.18, size * 0.84, size * 0.66, 20 * 16, 140 * 16)

    elif kind == "pencil":
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        # Lápis simples
        poly = QPolygonF([
            QPointF(size * 0.2, size * 0.7),
            QPointF(size * 0.5, size * 0.15),
            QPointF(size * 0.65, size * 0.28),
            QPointF(size * 0.35, size * 0.83),
        ])
        painter.drawPolygon(poly)
        # Ponta afiada
        painter.drawLine(QPointF(size * 0.2, size * 0.7), QPointF(size * 0.25, size * 0.65))

    elif kind == "trash":
        painter.setPen(pen)
        painter.setBrush(Qt.NoBrush)
        # Tampa
        line(size * 0.20, size * 0.30, size * 0.80, size * 0.30)
        line(size * 0.38, size * 0.20, size * 0.62, size * 0.20)
        # Cesto
        cesto = QPolygonF([
            QPointF(size * 0.26, size * 0.30),
            QPointF(size * 0.31, size * 0.82),
            QPointF(size * 0.69, size * 0.82),
            QPointF(size * 0.74, size * 0.30),
        ])
        painter.drawPolygon(cesto)
        # Linhas verticais internas
        line(size * 0.43, size * 0.40, size * 0.43, size * 0.72)
        line(size * 0.57, size * 0.40, size * 0.57, size * 0.72)

    painter.end()
    return QIcon(pm)

# ==========================================
# 1. MOTOR GRÁFICO PARA SINAIS 1D (ONDA ACÚSTICA)
# ==========================================
class HighPerfLineEngine:
    def __init__(self, ax, time_sec, data, base_color='#424242', update_bg_callback=None):
        self.ax = ax
        self.time_sec = time_sec
        self.data = data
        self.base_color = base_color
        self.update_bg_callback = update_bg_callback
        self.line = None
        
        self.debounce_timer = QTimer()
        self.debounce_timer.setSingleShot(True)
        self.debounce_timer.timeout.connect(self.render_high_detail)

    def get_viewport_slice(self, xmin, xmax):
        t_idx_min = max(0, np.searchsorted(self.time_sec, xmin) - 1)
        t_idx_max = min(len(self.time_sec), np.searchsorted(self.time_sec, xmax) + 1)
        if t_idx_max <= t_idx_min: t_idx_max = t_idx_min + 2
        return t_idx_min, t_idx_max

    def _get_envelope(self, t, y, max_points=4000):
        if len(y) <= max_points:
            return t, y
            
        num_blocks = max_points // 2
        block_size = len(y) // num_blocks
        
        y_trunc = y[:block_size * num_blocks].reshape(num_blocks, block_size)
        t_trunc = t[:block_size * num_blocks:block_size]
        
        y_min = y_trunc.min(axis=1)
        y_max = y_trunc.max(axis=1)
        
        t_env = np.empty(num_blocks * 2, dtype=t.dtype)
        y_env = np.empty(num_blocks * 2, dtype=y.dtype)
        
        t_env[0::2] = t_trunc
        t_env[1::2] = t_trunc
        y_env[0::2] = y_min
        y_env[1::2] = y_max
        
        return t_env, y_env

    def render_interactive(self, xmin, xmax, is_sync=False):
        self.debounce_timer.stop()
        t0, t1 = self.get_viewport_slice(xmin, xmax)
        
        pts = 400 if is_sync else 1000 
        t_env, y_env = self._get_envelope(self.time_sec[t0:t1], self.data[t0:t1], max_points=pts)
        self._update_plot(t_env, y_env)
        
        self.debounce_timer.start(200 if is_sync else 150)

    def render_high_detail(self):
        xmin, xmax = self.ax.get_xlim()
        t0, t1 = self.get_viewport_slice(xmin, xmax)
        
        t_env, y_env = self._get_envelope(self.time_sec[t0:t1], self.data[t0:t1], max_points=4000)
        self._update_plot(t_env, y_env)
        
        if self.update_bg_callback:
            QTimer.singleShot(50, self.update_bg_callback)

    def _update_plot(self, t, y):
        if self.line is None:
            self.line, = self.ax.plot(t, y, color=self.base_color, zorder=1, antialiased=False)
        else:
            self.line.set_data(t, y)
        self.ax.figure.canvas.draw_idle()

