class PlotPanel(QWidget):
    """Card de gráfico reutilizável. A posição no dashboard é controlada por MainWindow."""
    def __init__(self, title_key, lang, expand_callback, main=False):
        super().__init__()
        self.title_key = title_key
        self.expand_callback = expand_callback
        self.pulse_edit_mode = False
        self.layout = QVBoxLayout(self)
        self.layout.setContentsMargins(0, 0, 0, 0)
        self.layout.setSpacing(0)

        self.title_bar = QWidget()
        self.title_bar.setObjectName("plotTitleBar")
        self.title_bar.setAttribute(Qt.WA_TranslucentBackground, True)
        bar = QHBoxLayout(self.title_bar)
        bar.setContentsMargins(12, 7, 8, 7)
        bar.setSpacing(4)

        self.lbl_title = QLabel(I18N[lang][title_key])
        self.lbl_title.setObjectName("plotTitle")
        bar.addWidget(self.lbl_title)
        bar.addStretch()

        # Botão de edição de pulsos (ativa/desativa modo de seleção)
        self.btn_pulse_edit = self._tool_button("", "Ativar modo de edição de pulsos (clique para adicionar/remover)")
        self.btn_pulse_edit.setObjectName("plotTool")
        self.btn_pulse_edit.setIcon(make_ui_icon("pencil", color="#D7DCE2", size=15))
        self.btn_pulse_edit.setIconSize(QSize(14, 14))
        self.btn_pulse_edit.setCheckable(True)
        self.btn_pulse_edit.toggled.connect(self._toggle_pulse_edit_mode)
        bar.addWidget(self.btn_pulse_edit)

        self.btn_pulse_undo = self._tool_button("↶", "Desfazer última edição de pulso")
        self.btn_pulse_undo.setEnabled(False)
        self.btn_pulse_undo.clicked.connect(
            lambda: self.window()._undo_pulse_edit()
            if hasattr(self.window(), "_undo_pulse_edit") else None
        )
        bar.addWidget(self.btn_pulse_undo)

        # Ações do gráfico: somente maximizar/restaurar, que possui comportamento real.
        self.btn_expand = self._tool_button("", "Colocar este gráfico na posição principal")
        self.btn_expand.setObjectName("plotMaximize")
        self.btn_expand.setIcon(make_ui_icon("maximize", color="#D7DCE2", size=15))
        self.btn_expand.setIconSize(QSize(14, 14))
        self.btn_expand.clicked.connect(lambda: self.expand_callback(self))
        bar.addWidget(self.btn_expand)

        self.figure = Figure(facecolor="#141517")
        self.figure.subplots_adjust(left=0.07, right=0.985, top=0.94, bottom=0.12)
        self.canvas = FigureCanvas(self.figure)
        self.canvas.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.canvas.setStyleSheet("background:transparent; border:0; padding:0; margin:0;")
        self.ax = self.figure.add_subplot(111, facecolor="#101214")
        self.apply_dark_theme()

        self.layout.addWidget(self.title_bar)
        self.layout.addWidget(self.canvas, 1)

        self.setObjectName("plotCard")
        self.setAttribute(Qt.WA_StyledBackground, True)
        self.setAttribute(Qt.WA_TranslucentBackground, False)
        self._set_main_visual(main)

    def _tool_button(self, glyph, tooltip):
        b = QPushButton(glyph)
        b.setFlat(True)
        b.setFocusPolicy(Qt.NoFocus)
        b.setToolTip(tooltip)
        b.setFixedSize(28, 26)
        b.setObjectName("plotTool")
        return b

    def _toggle_pulse_edit_mode(self, checked):
        """Ativa/desativa o modo de edição de pulsos para este painel."""
        self.pulse_edit_mode = checked
        parent = self.window()
        if hasattr(parent, '_update_pulse_edit_buttons'):
            parent._update_pulse_edit_buttons(self)
        if checked:
            self.btn_pulse_edit.setToolTip("Modo de edição ativo! Clique nos picos para adicionar/remover")
            self.btn_pulse_edit.setStyleSheet("QPushButton { background: #1F6FEB; border-radius: 4px; }")
        else:
            self.btn_pulse_edit.setToolTip("Ativar modo de edição de pulsos (clique para adicionar/remover)")
            self.btn_pulse_edit.setStyleSheet("")


    def _set_main_visual(self, main):
        self.setProperty("mainPlot", bool(main))
        self.style().unpolish(self)
        self.style().polish(self)

    def set_main(self, main):
        self._set_main_visual(main)
        self.btn_expand.setToolTip(
            "Restaurar posição" if main else "Colocar este gráfico na posição principal"
        )

    def update_lang(self, lang):
        self.lbl_title.setText(I18N[lang][self.title_key])

    def apply_dark_theme(self):
        dark = getattr(self.window(), "theme_mode", "dark") == "dark"
        fg = "#A9ADB5" if dark else "#59616B"
        spine = "#2A2D32" if dark else "#D7DDE3"
        grid = "#25282D" if dark else "#DDE2E7"
        face = "#101214" if dark else "#FFFFFF"
        fig_face = "#141517" if dark else "#F7F9FB"
        self.figure.set_facecolor(fig_face)
        self.figure.patch.set_alpha(1.0)
        self.ax.set_facecolor(face)
        self.ax.patch.set_alpha(1.0)
        self.ax.tick_params(colors=fg, labelsize=8, length=3, width=0.8)
        for sp in self.ax.spines.values():
            sp.set_color(spine)
            sp.set_linewidth(0.8)
        self.ax.xaxis.label.set_color(fg)
        self.ax.yaxis.label.set_color(fg)
        self.ax.grid(color=grid, linewidth=0.6, alpha=0.65)


class TimelineWidget(QWidget):
    """Régua de reprodução/inspeção com ticks, timestamps e flags de chilreios."""
    def __init__(self, position_callback, parent=None):
        super().__init__(parent)
        self.position_callback = position_callback
        self.duration = 0.0
        self.position = 0.0
        self.markers = []
        self.is_dragging = False
        self.setMinimumHeight(92)
        self.setMaximumHeight(104)
        self.setMouseTracking(True)
        self.setAttribute(Qt.WA_TranslucentBackground, True)
        self.setAutoFillBackground(False)

    def set_data(self, duration, markers):
        self.duration = max(0.0, float(duration or 0.0))
        self.markers = list(markers or [])
        self.update()

    def set_position(self, seconds):
        if not self.is_dragging:
            self.position = max(0.0, min(float(seconds), self.duration or 0.0))
            self.update()

    def _x_for(self, seconds, left, right):
        if self.duration <= 0:
            return left
        return left + (right - left) * (seconds / self.duration)

    def _seconds_from_event(self, event):
        left, right = 18, max(19, self.width() - 18)
        if hasattr(event, "pos"):
            ex = float(event.pos().x())
        elif hasattr(event, "position"):
            ex = float(event.position().x())
        else:
            ex = float(getattr(event, "x", lambda: 0)())

        ratio = max(0.0, min(1.0, (ex - left) / max(1.0, float(right - left))))
        return ratio * self.duration

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton and self.duration > 0:
            self.is_dragging = True
            sec = self._seconds_from_event(event)
            self.position = sec
            self.update()
            if self.position_callback:
                self.position_callback(sec * 1000.0, is_final=False)
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self.is_dragging and self.duration > 0:
            sec = self._seconds_from_event(event)
            self.position = sec
            self.update()
            if self.position_callback:
                self.position_callback(sec * 1000.0, is_final=False)
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.LeftButton:
            if self.is_dragging and self.duration > 0:
                sec = self._seconds_from_event(event)
                self.position = sec
                self.update()
                if self.position_callback:
                    self.position_callback(sec * 1000.0, is_final=True)
            self.is_dragging = False
        super().mouseReleaseEvent(event)

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        dark = getattr(self.window(), "theme_mode", "dark") == "dark"
        bg = QColor("#111214") if dark else QColor("#F7F9FB")
        rail = QColor("#363A41") if dark else QColor("#C9D0D7")
        major = QColor("#A0A5AE") if dark else QColor("#64707C")
        minor = QColor("#353940") if dark else QColor("#D8DEE4")
        text = QColor("#8F949D") if dark else QColor("#65707A")
        left, right = 18, max(19, self.width() - 18)
        ruler_y = 45

        # trilho principal
        p.setPen(rail)
        p.drawLine(left, ruler_y, right, ruler_y)

        if self.duration <= 0:
            p.setPen(text)
            p.drawText(18, 20, "0.00")
            p.end()
            return

        # ticks finos a cada 1s e ticks principais a cada 10s
        major_step = 10.0
        if self.duration < 30:
            major_step = 5.0
        elif self.duration > 180:
            major_step = 20.0

        sec = 0.0
        while sec <= self.duration + 1e-6:
            x = self._x_for(sec, left, right)
            is_major = abs((sec / major_step) - round(sec / major_step)) < 1e-5
            tick_h = 11 if is_major else 5
            p.setPen(major if is_major else minor)
            p.drawLine(int(x), ruler_y-tick_h, int(x), ruler_y+2)
            if is_major:
                p.setPen(major)
                label = self._format_time(sec)
                p.drawText(int(x)-28, 72, 56, 14, Qt.AlignCenter, label)
            sec += 1.0

        # faixa discreta de progresso
        progress_x = self._x_for(self.position, left, right)
        p.setPen(QColor("#3B8EDB"))
        p.drawLine(left, ruler_y, int(progress_x), ruler_y)

        # flags dos eventos analisados
        for idx, marker in enumerate(self.markers):
            t = marker.get("time", 0.0) if isinstance(marker, dict) else float(marker)
            color = marker.get("color", "#F0A54A") if isinstance(marker, dict) else ("#F0A54A" if idx % 2 == 0 else "#4D9DE0")
            x = int(self._x_for(t, left, right))
            p.setPen(QColor(color))
            p.setBrush(QColor(color))
            p.drawLine(x, 15, x, ruler_y)
            pts = QPolygonF([QPointF(x, 14), QPointF(x+9, 18), QPointF(x+9, 27), QPointF(x, 31)])
            p.drawPolygon(pts)

        # cursor branco
        cursor_x = int(progress_x)
        p.setPen(QColor("#F2F3F5"))
        p.drawLine(cursor_x, 7, cursor_x, 78)
        p.setBrush(QColor("#F2F3F5"))
        p.drawRoundedRect(cursor_x-4, 5, 8, 7, 2, 2)

        p.setPen(text)
        # Tempo corrente e duração ficam na faixa inferior, separados das flags.
        p.setPen(text)
        p.drawText(18, 88, 74, 14, Qt.AlignLeft, self._format_time(self.position) )
        p.drawText(right-74, 88, 74, 14, Qt.AlignRight, self._format_time(self.duration) )
        p.end()

    @staticmethod
    def _format_time(seconds):
        seconds = max(0.0, float(seconds))
        minutes = int(seconds // 60)
        secs = seconds - minutes * 60
        return f"{minutes:02d}:{secs:05.2f}"


class ThemeToggle(QCheckBox):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setFixedSize(46, 24)
        self.setCursor(Qt.PointingHandCursor)
        self.setFocusPolicy(Qt.NoFocus)
        self.setChecked(False)
        self.setStyleSheet("QCheckBox{background:transparent;border:0;} QCheckBox::indicator{width:44px;height:22px;border:0;background:transparent;}" )
    def paintEvent(self, event):
        p=QPainter(self); p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        dark=getattr(self.window(),'theme_mode','dark')=='dark'
        track=QColor('#2A2E33' if dark else '#D6DDE4'); active=QColor('#2E8ED8'); border=QColor('#444A52' if dark else '#B8C1CA')
        p.setPen(QPen(border,1)); p.setBrush(active if self.isChecked() else track); p.drawRoundedRect(QRectF(1,1,44,22),11,11)
        x=33 if self.isChecked() else 13
        p.setPen(Qt.NoPen); p.setBrush(QColor('#FFFFFF')); p.drawEllipse(QRectF(x-8,4,16,16)); p.end()


# ==========================================
# TELA DE LOADING / SPLASH
# ==========================================
class LoadingScreen(QWidget):
    """Tela inicial sem moldura que reproduz loading.mp4 antes da janela principal."""
    def __init__(self, parent=None, finish_callback=None):
        super().__init__(parent)
        self.setWindowFlags(
            Qt.FramelessWindowHint |
            Qt.WindowStaysOnTopHint |
            Qt.Tool
        )
        self.setAttribute(Qt.WA_DeleteOnClose, True)
        self.finish_callback = finish_callback
        self.setStyleSheet("background: #0D0F11;")

        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        self.video = QVideoWidget(self)
        self.video.setStyleSheet("background: transparent; border: 0;")
        layout.addWidget(self.video)

        self.player = QMediaPlayer(self)
        self.audio = QAudioOutput(self)
        self.audio.setVolume(1.0)  # reproduz também a trilha de áudio do loading.mp4
        self.player.setVolume(100)
        self.player.setVideoOutput(self.video)

        self.player.mediaStatusChanged.connect(self._on_media_status)
        self.player.errorOccurred.connect(self._on_error)
        self.finished.connect(lambda: None) if False else None

        self._fallback = QTimer(self)
        self._fallback.setSingleShot(True)
        self._fallback.timeout.connect(self.finish)

        self._finished = False

        video_path = self._asset_path("loading.mp4")
        if os.path.exists(video_path):
            self.player.setMedia(QMediaContent(QUrl.fromLocalFile(video_path)))
            self.player.play()
            self._fallback.start(15000)
        else:
            self.finish()

        self._center_on_screen()

    @staticmethod
    def _asset_path(filename):
        # PyInstaller --onefile extrai --add-data para _MEIPASS.
        base = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
        return os.path.join(base, filename)

    def _center_on_screen(self):
        screen = QApplication.primaryScreen()
        if not screen:
            self.resize(640, 360)
            return
        available = screen.availableGeometry()
        # 16:9, ocupando no máximo ~70% da tela para manter aspecto de splash.
        w = min(900, int(available.width() * 0.70))
        h = int(w * 9 / 16)
        if h > int(available.height() * 0.70):
            h = int(available.height() * 0.70)
            w = int(h * 16 / 9)
        self.resize(max(480, w), max(270, h))
        geo = self.geometry()
        geo.moveCenter(available.center())
        self.setGeometry(geo)

    def _on_media_status(self, status):
        if status == QMediaPlayer.MediaStatus.EndOfMedia:
            self.finish()

    def _on_error(self, *args):
        self.finish()

    def finish(self):
        if self._finished:
            return
        self._finished = True
        self._fallback.stop()
        self.player.stop()
        callback = self.finish_callback
        self.finish_callback = None
        self.close()
        if callback:
            QTimer.singleShot(0, callback)

class AudioListItemWidget(QWidget):
    """Widget para item da lista de áudios contendo:
    - Um card clicável com o nome do áudio (com efeito hover e seleção ativa).
    - Fora do card, no canto direito: a caixinha de seleção (azul quando marcada) e o botão de lixeira.
    """
    def __init__(self, filename, is_checked=True, is_active=False, on_toggle=None, on_delete=None, on_select=None, parent=None):
        super().__init__(parent)
        self.filename = filename
        self.on_delete = on_delete
        self.on_toggle = on_toggle
        self.on_select = on_select

        main_layout = QHBoxLayout(self)
        main_layout.setContentsMargins(1, 1, 1, 1)
        main_layout.setSpacing(6)

        # 1. Card de clique / hover do áudio (exclusivo para o nome do arquivo)
        self.card = QFrame()
        self.card.setObjectName("audioFileCard")
        self.card.setProperty("active", is_active)
        self.card.setCursor(Qt.PointingHandCursor)
        
        card_layout = QHBoxLayout(self.card)
        card_layout.setContentsMargins(8, 4, 8, 4)
        card_layout.setSpacing(6)

        self.lbl_icon = QLabel()
        self.lbl_icon.setPixmap(make_ui_icon("play", color="#8B949E", size=10).pixmap(10, 10))
        self.lbl_icon.setStyleSheet("background: transparent; border: 0;")
        card_layout.addWidget(self.lbl_icon)

        self.lbl_name = QLabel(filename)
        self.lbl_name.setObjectName("audioFileName")
        self.lbl_name.setToolTip(filename)
        self.lbl_name.setStyleSheet("background: transparent; border: 0;")
        card_layout.addWidget(self.lbl_name, 1)

        main_layout.addWidget(self.card, 1)

        # 2. Área no canto direito (FORA do card de clique/hover do áudio)
        self.actions_widget = QWidget()
        self.actions_widget.setStyleSheet("background: transparent; border: 0;")
        actions_layout = QHBoxLayout(self.actions_widget)
        actions_layout.setContentsMargins(0, 0, 0, 0)
        actions_layout.setSpacing(4)

        # Caixinha de marcar (fica azul quando selecionada)
        self.checkbox = QCheckBox()
        self.checkbox.setChecked(is_checked)
        self.checkbox.setToolTip("Marcar para análise em lote e relatório")
        self.checkbox.setCursor(Qt.PointingHandCursor)
        self.checkbox.stateChanged.connect(self._on_check_changed)
        actions_layout.addWidget(self.checkbox)

        # Botão com ícone de lixeira para remover o áudio
        self.btn_trash = QPushButton()
        self.btn_trash.setFixedSize(22, 22)
        self.btn_trash.setFlat(True)
        self.btn_trash.setIcon(make_ui_icon("trash", color="#8B949E", size=14))
        self.btn_trash.setToolTip(f"Remover {filename} da lista")
        self.btn_trash.setCursor(Qt.PointingHandCursor)
        self.btn_trash.setStyleSheet("""
            QPushButton { background: transparent; border: 0; border-radius: 4px; padding: 2px; }
            QPushButton:hover { background: rgba(239, 68, 68, 0.25); }
        """)
        self.btn_trash.clicked.connect(self._on_delete_clicked)
        actions_layout.addWidget(self.btn_trash)

        main_layout.addWidget(self.actions_widget, 0)

        # Evento de clique no card para selecionar o áudio
        self.card.mousePressEvent = self._on_card_clicked

    def _on_card_clicked(self, event):
        if self.on_select:
            self.on_select(self.filename)

    def set_active(self, active):
        self.card.setProperty("active", bool(active))
        self.card.style().unpolish(self.card)
        self.card.style().polish(self.card)
        self.lbl_name.style().unpolish(self.lbl_name)
        self.lbl_name.style().polish(self.lbl_name)

    def is_checked(self):
        return self.checkbox.isChecked()

    def set_checked(self, checked):
        self.checkbox.setChecked(checked)

    def _on_check_changed(self, state):
        if self.on_toggle:
            self.on_toggle(self.filename, state == Qt.Checked or state == 2)

    def _on_delete_clicked(self):
        if self.on_delete:
            self.on_delete(self.filename)


